contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint amount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (amount)); require(amount <= 1000000000000000000000000000000);
        require(amount > 0);
        require(address(this).balance >= amount);

        uint balanceBefore = address(c).balance;
        uint selfBefore = address(this).balance;

        c.deposit{value: amount}(); if (__ESBMC_reverted()) return;

        bool reverted;
        c.withdrawAll(); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        uint selfAfter = address(this).balance;

        // Ether returned to this contract during withdrawAll, accounting for the deposit we sent.
        uint returnedEther = selfAfter + amount - selfBefore;

        // Remaining credit is observable indirectly: c's balance must cover it.
        uint remainingCredit;
        if (address(c).balance >= balanceBefore) {
            remainingCredit = address(c).balance - balanceBefore;
        }

        assert(reverted || (returnedEther + remainingCredit == amount));
    }

    receive() external payable {}
}

