pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {ReentrancyDAO} from "../src/ReentrancyDAO.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    ReentrancyDAO c;

    function setUp() public {
        c = new ReentrancyDAO();
    }

    function _run(uint256 amount) internal {
        amount = bound(amount, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(amount > 0);
        vm.assume(address(this).balance >= amount);
        uint balanceBefore = address(c).balance;
        uint selfBefore = address(this).balance;
        try c.deposit{value: amount}() {} catch { return; }
        bool reverted;
        try c.withdrawAll() {
            reverted = false;
        } catch {
            reverted = true;
        }
        uint selfAfter = address(this).balance;
        uint returnedEther = selfAfter + amount - selfBefore;
        uint remainingCredit;
        if (address(c).balance >= balanceBefore) {
            remainingCredit = address(c).balance - balanceBefore;
        }
        assertTrue(reverted || (returnedEther + remainingCredit == amount));
    }

    function testFuzz_run(uint256 amount) public {
        _run(amount);
    }

    receive() external payable {}
}
